insert into "frameworks" ("framework_id", "framework_code", "framework_name", "creator", "category", "what_it_is", "problem_it_solves", "stage_relevance", "industry_relevance", "how_alley_uses_it", "linked_root_cause_ids", "linked_intervention_ids", "source_reference", "created_at", "updated_at") values ('1', 'FW-001', 'The Mom Test', 'Rob Fitzpatrick', 'Idea & Validation', 'A customer interview framework that teaches founders how to ask questions that reveal the truth — not the answers people think you want to hear. Focuses on asking about past behaviour rather than future intentions.', 'Founders getting false validation from biased interviews — especially from friends and family who say ''great idea'' without meaning it.', '[1, 2, 3]', '["all"]', 'Referenced in intervention for ''Lack of Customer Discovery'' and ''No Validation.'' Used as the primary tool for customer interview structure in the Question Bank.', '["RC-001", "RC-002", "RC-003"]', '["INT-019"]', 'The Mom Test — Rob Fitzpatrick (2013)', '2026-07-10 17:55:46.360166+00', '2026-07-10 17:55:46.360166+00') on conflict do nothing;
insert into "frameworks" ("framework_id", "framework_code", "framework_name", "creator", "category", "what_it_is", "problem_it_solves", "stage_relevance", "industry_relevance", "how_alley_uses_it", "linked_root_cause_ids", "linked_intervention_ids", "source_reference", "created_at", "updated_at") values ('2', 'FW-002', 'Lean Canvas', 'Ash Maurya', 'Idea & Validation', 'A one-page business plan template that focuses on problems, solutions, key metrics, and unfair advantages. A simplified, action-focused version of the Business Model Canvas designed for early-stage startups.', 'Founders building without a clear problem-solution hypothesis. Prevents the common mistake of building a solution before validating the problem.', '[1, 2]', '["all"]', 'Used in intervention for ''Building Before Problem Framing.'' Recommended as the first structured planning tool before any development begins.', '["RC-001", "RC-002", "RC-003"]', '["INT-021"]', 'Running Lean — Ash Maurya (2012)', '2026-07-10 17:55:46.360166+00', '2026-07-10 17:55:46.360166+00') on conflict do nothing;
insert into "frameworks" ("framework_id", "framework_code", "framework_name", "creator", "category", "what_it_is", "problem_it_solves", "stage_relevance", "industry_relevance", "how_alley_uses_it", "linked_root_cause_ids", "linked_intervention_ids", "source_reference", "created_at", "updated_at") values ('3', 'FW-003', 'Jobs-To-Be-Done (JTBD)', 'Clayton Christensen', 'Idea & Validation', 'A framework that reframes customer needs around the progress the customer is trying to make — the ''job'' they are hiring a product to do. Separates functional, emotional, and social jobs.', 'Founders building products around features rather than customer progress. Reveals what the customer actually values versus what the founder assumes they value.', '[1, 2, 3, 4]', '["all"]', 'Referenced across multiple root cause mappings. Used in the Agent Interpretation Table to probe beneath surface statements like ''customers don''t understand our product.''', '["RC-001", "RC-002", "RC-003"]', '["INT-078"]', 'Competing Against Luck — Clayton Christensen (2016)', '2026-07-10 17:55:46.360166+00', '2026-07-10 17:55:46.360166+00') on conflict do nothing;
insert into "frameworks" ("framework_id", "framework_code", "framework_name", "creator", "category", "what_it_is", "problem_it_solves", "stage_relevance", "industry_relevance", "how_alley_uses_it", "linked_root_cause_ids", "linked_intervention_ids", "source_reference", "created_at", "updated_at") values ('4', 'FW-004', 'Assumption Mapping', 'Strategyzer', 'Idea & Validation', 'A structured method to identify and prioritise the assumptions in a business model by risk level. Maps assumptions on two axes: how important they are to the business and how much evidence exists for them.', 'Founders building on unvalidated assumptions without realising which ones are most dangerous to the business if wrong.', '[1, 2, 3]', '["all"]', 'Recommended in intervention for ''Building Before Problem Framing.'' Helps founders identify their riskiest assumption before writing a single line of code.', '["RC-001", "RC-002", "RC-003"]', '["INT-040", "INT-021"]', 'Testing Business Ideas — Strategyzer (2019)', '2026-07-10 17:55:46.360166+00', '2026-07-10 17:55:46.360166+00') on conflict do nothing;
insert into "frameworks" ("framework_id", "framework_code", "framework_name", "creator", "category", "what_it_is", "problem_it_solves", "stage_relevance", "industry_relevance", "how_alley_uses_it", "linked_root_cause_ids", "linked_intervention_ids", "source_reference", "created_at", "updated_at") values ('5', 'FW-005', 'Smoke Test / Landing Page Test', 'Eric Ries / Lean Startup community', 'Idea & Validation', 'A pre-launch validation method where a founder builds a minimal landing page describing the product and measures real interest through sign-ups, clicks, or pre-orders — before building anything.', 'Founders investing months of development before knowing whether anyone actually wants the product.', '[1, 2]', '["all"]', 'Recommended as an immediate next step in the intervention for ''No Real Market Need.'' The cheapest and fastest way to test demand with real behaviour rather than opinion.', '["RC-001", "RC-002", "RC-003"]', '["INT-001"]', 'The Lean Startup — Eric Ries (2011)', '2026-07-10 17:55:46.360166+00', '2026-07-10 17:55:46.360166+00') on conflict do nothing;
insert into "frameworks" ("framework_id", "framework_code", "framework_name", "creator", "category", "what_it_is", "problem_it_solves", "stage_relevance", "industry_relevance", "how_alley_uses_it", "linked_root_cause_ids", "linked_intervention_ids", "source_reference", "created_at", "updated_at") values ('6', 'FW-006', 'Build-Measure-Learn Loop', 'Eric Ries', 'Idea & Validation', 'The core cycle of the Lean Startup methodology. Build the smallest possible version of an idea, measure how real users respond, learn from the data, and repeat. The loop replaces the traditional build-then-launch approach.', 'Founders spending too long building before getting feedback. Reduces the cost of being wrong by shortening the feedback cycle.', '[1, 2, 3, 4]', '["all"]', 'Referenced throughout the Question Bank and Intervention Library. Used as the guiding principle for any root cause involving ''over-engineering'' or ''lack of feedback loop.''', '["RC-001", "RC-002", "RC-003"]', '["INT-020", "INT-011"]', 'The Lean Startup — Eric Ries (2011)', '2026-07-10 17:55:46.360166+00', '2026-07-10 17:55:46.360166+00') on conflict do nothing;
insert into "frameworks" ("framework_id", "framework_code", "framework_name", "creator", "category", "what_it_is", "problem_it_solves", "stage_relevance", "industry_relevance", "how_alley_uses_it", "linked_root_cause_ids", "linked_intervention_ids", "source_reference", "created_at", "updated_at") values ('7', 'FW-007', 'Problem Ranking Matrix', 'Founder Ally / GoXL', 'Idea & Validation', 'A structured evaluation tool for ranking multiple potential problems by urgency, frequency, willingness to pay, and market size. Helps founders choose which problem to solve first when multiple options exist.', 'Founders choosing a problem based on personal interest rather than market opportunity. Creates an objective basis for problem selection.', '[1, 2]', '["all"]', 'Used in the intervention for ''Poor Problem Selection.'' The ranking matrix is one of the three immediate next steps recommended to founders struggling with problem selection.', '["RC-001", "RC-002", "RC-003"]', '["INT-019"]', 'Founder Ally Intervention Library — Doc 8', '2026-07-10 17:55:46.360166+00', '2026-07-10 17:55:46.360166+00') on conflict do nothing;
insert into "frameworks" ("framework_id", "framework_code", "framework_name", "creator", "category", "what_it_is", "problem_it_solves", "stage_relevance", "industry_relevance", "how_alley_uses_it", "linked_root_cause_ids", "linked_intervention_ids", "source_reference", "created_at", "updated_at") values ('8', 'FW-008', 'Opportunity Solution Tree', 'Teresa Torres', 'Idea & Validation', 'A visual framework that separates desired outcomes, customer opportunities, and potential solutions. Forces founders to start with what the customer needs to achieve before jumping to solutions.', 'Founders who jump from problem straight to solution without understanding the full opportunity space. Prevents premature solution commitment.', '[1, 2, 3, 4]', '["all"]', 'Referenced in the intervention for ''Building Before Problem Framing'' and ''No Clear Product Vision.'' Used to structure how Founder Ally frames the relationship between root causes and interventions.', '["RC-001", "RC-002", "RC-003"]', '["INT-019"]', 'Continuous Discovery Habits — Teresa Torres (2021)', '2026-07-10 17:55:46.360166+00', '2026-07-10 17:55:46.360166+00') on conflict do nothing;
insert into "frameworks" ("framework_id", "framework_code", "framework_name", "creator", "category", "what_it_is", "problem_it_solves", "stage_relevance", "industry_relevance", "how_alley_uses_it", "linked_root_cause_ids", "linked_intervention_ids", "source_reference", "created_at", "updated_at") values ('9', 'FW-009', 'Pretotype Framework', 'Alberto Savoia', 'Idea & Validation', 'A validation method that tests whether the right people will use the right product in the right context — before building a full prototype. Uses the minimum possible effort to validate real interest.', 'Founders building full prototypes before validating that anyone will actually use the product. ''Build the right it before you build it right.''', '[1, 2]', '["all"]', 'Used in intervention for ''Over-Engineering and Perfectionism.'' Recommended as an alternative to building when founders are trapped in perfectionism.', '["RC-001", "RC-002", "RC-003"]', '["INT-040"]', 'Pretotype It — Alberto Savoia (2011)', '2026-07-10 17:55:46.360166+00', '2026-07-10 17:55:46.360166+00') on conflict do nothing;
insert into "frameworks" ("framework_id", "framework_code", "framework_name", "creator", "category", "what_it_is", "problem_it_solves", "stage_relevance", "industry_relevance", "how_alley_uses_it", "linked_root_cause_ids", "linked_intervention_ids", "source_reference", "created_at", "updated_at") values ('10', 'FW-010', 'Willingness-to-Pay Interview', 'Founder Ally / GoXL synthesis', 'Idea & Validation', 'A structured customer interview technique focused specifically on pricing. Asks customers directly about price sensitivity, acceptable ranges, and what would make them switch to or from a solution.', 'Founders pricing by gut feeling or competitor copying rather than real customer data. The most reliable way to discover what customers will actually pay.', '[1, 2, 3, 4]', '["all"]', 'Recommended in interventions for ''Neglecting Pricing Strategy'' and ''Pricing and Unit-Economics Confusion.'' One of the three immediate next steps for pricing root causes.', '["RC-001", "RC-002", "RC-003"]', '["INT-001"]', 'Founder Ally Intervention Library — Doc 8', '2026-07-10 17:55:46.360166+00', '2026-07-10 17:55:46.360166+00') on conflict do nothing;
insert into "frameworks" ("framework_id", "framework_code", "framework_name", "creator", "category", "what_it_is", "problem_it_solves", "stage_relevance", "industry_relevance", "how_alley_uses_it", "linked_root_cause_ids", "linked_intervention_ids", "source_reference", "created_at", "updated_at") values ('11', 'FW-011', 'ICP Builder (Ideal Customer Profile)', 'Founder Ally / GoXL synthesis', 'Go-To-Market', 'A structured framework for defining the ideal customer using firmographics, psychographics, behaviours, pain severity, and trigger events. Goes beyond basic demographics to identify customers most likely to buy, stay, and refer.', 'Founders targeting too broadly or defining customers by vague characteristics like ''SMBs in India.'' Precision targeting reduces wasted sales and marketing effort.', '[2, 3, 4, 5]', '["all"]', 'Directly feeds the onboarding question ''Who is your ideal customer?'' Used in the root cause assessment for GTM failures and weak pipeline. One of the most referenced frameworks in Founder Ally.', '["RC-073", "RC-074", "RC-075"]', '["INT-003"]', 'Founder Ally Intervention Library — Doc 8 / Doc 9', '2026-07-10 17:55:46.360166+00', '2026-07-10 17:55:46.360166+00') on conflict do nothing;
insert into "frameworks" ("framework_id", "framework_code", "framework_name", "creator", "category", "what_it_is", "problem_it_solves", "stage_relevance", "industry_relevance", "how_alley_uses_it", "linked_root_cause_ids", "linked_intervention_ids", "source_reference", "created_at", "updated_at") values ('12', 'FW-012', 'Beachhead Market Strategy', 'Geoffrey Moore', 'Go-To-Market', 'A market entry strategy where the founder picks one very narrow segment to dominate completely before expanding. Named after the military tactic of securing a small beach position before advancing inland.', 'Founders trying to serve everyone at once and serving no one well. Concentrating resources on one beachhead creates a repeatable success pattern before scaling.', '[1, 2, 3, 4]', '["all"]', 'Referenced in interventions for ''Undefined ICP'' and ''Wrong GTM.'' Used as the primary recommendation when the root cause is ''fear of missing customers'' or overly broad targeting.', '["RC-073", "RC-074", "RC-075"]', '["INT-003", "INT-018"]', 'Crossing the Chasm — Geoffrey Moore (1991)', '2026-07-10 17:55:46.360166+00', '2026-07-10 17:55:46.360166+00') on conflict do nothing;
insert into "frameworks" ("framework_id", "framework_code", "framework_name", "creator", "category", "what_it_is", "problem_it_solves", "stage_relevance", "industry_relevance", "how_alley_uses_it", "linked_root_cause_ids", "linked_intervention_ids", "source_reference", "created_at", "updated_at") values ('13', 'FW-013', 'Bullseye Framework', 'Gabriel Weinberg & Justin Mares', 'Go-To-Market', 'A systematic channel testing framework where founders test all 19 possible traction channels through three concentric circles — outer (all channels), middle (top 6), inner (best 3) — narrowing to the most effective.', 'Founders choosing channels based on what is trendy rather than what works for their specific business. Creates a data-driven basis for channel investment.', '[2, 3, 4]', '["all"]', 'Used in intervention for ''Wrong or Untested Channels.'' The Bullseye is the recommended first tool for any founder whose root cause involves channel assumptions or untested channel investments.', '["RC-073", "RC-074", "RC-075"]', '["INT-023"]', 'Traction — Gabriel Weinberg & Justin Mares (2014)', '2026-07-10 17:55:46.360166+00', '2026-07-10 17:55:46.360166+00') on conflict do nothing;
insert into "frameworks" ("framework_id", "framework_code", "framework_name", "creator", "category", "what_it_is", "problem_it_solves", "stage_relevance", "industry_relevance", "how_alley_uses_it", "linked_root_cause_ids", "linked_intervention_ids", "source_reference", "created_at", "updated_at") values ('14', 'FW-014', 'Obviously Awesome Positioning Framework', 'April Dunford', 'Go-To-Market', 'A 5-step framework for defining competitive positioning: identify competitive alternatives, isolate unique attributes, define the value these attributes enable, identify target customers who care most about this value, and name the market category.', 'Founders with weak or confusing positioning — products that sound like everything else or mean nothing to the customer. Positioning failure is one of the top causes of GTM and messaging failure.', '[2, 3, 4, 5]', '["all"]', 'Referenced in intervention for ''Poor Positioning & Messaging.'' Used in the Agent Interpretation Table to probe beneath statements like ''customers don''t get what we do.''', '["RC-073", "RC-074", "RC-075"]', '["INT-004"]', 'Obviously Awesome — April Dunford (2019)', '2026-07-10 17:55:46.360166+00', '2026-07-10 17:55:46.360166+00') on conflict do nothing;
insert into "frameworks" ("framework_id", "framework_code", "framework_name", "creator", "category", "what_it_is", "problem_it_solves", "stage_relevance", "industry_relevance", "how_alley_uses_it", "linked_root_cause_ids", "linked_intervention_ids", "source_reference", "created_at", "updated_at") values ('15', 'FW-015', 'Value Proposition Canvas', 'Alexander Osterwalder', 'Go-To-Market', 'A tool for ensuring the product creates value for customers by mapping customer jobs, pains, and gains against the product''s pain relievers and gain creators. Ensures the product actually fits what the customer needs.', 'Founders building products that do not match what the customer cares about. The Value Proposition Canvas makes the fit — or the gap — visible.', '[1, 2, 3, 4]', '["all"]', 'Used in interventions for ''Poor Positioning,'' ''No Product-Market Fit,'' and ''Sacrificing User Needs for Monetisation.'' One of the most versatile frameworks in the Founder Ally library.', '["RC-073", "RC-074", "RC-075"]', '["INT-004", "INT-043", "INT-081"]', 'Value Proposition Design — Osterwalder et al. (2014)', '2026-07-10 17:55:46.360166+00', '2026-07-10 17:55:46.360166+00') on conflict do nothing;
insert into "frameworks" ("framework_id", "framework_code", "framework_name", "creator", "category", "what_it_is", "problem_it_solves", "stage_relevance", "industry_relevance", "how_alley_uses_it", "linked_root_cause_ids", "linked_intervention_ids", "source_reference", "created_at", "updated_at") values ('16', 'FW-016', 'AARRR Funnel (Pirate Metrics)', 'Dave McClure', 'Go-To-Market', 'A framework that breaks the growth funnel into five stages: Acquisition, Activation, Retention, Referral, and Revenue. Helps founders identify where in the funnel their biggest growth leaks are.', 'Founders obsessing over acquisition while ignoring retention and activation. The AARRR framework forces attention across the entire customer lifecycle.', '[3, 4, 5, 6]', '["saas", "manufacturing"]', 'Referenced in interventions for ''Over-Focusing on Acquisition'' and ''Ignoring Retention.'' Used in the scoring engine to weight GTM questions toward the appropriate funnel stage.', '["RC-073", "RC-074", "RC-075"]', '["INT-026", "INT-023"]', 'Dave McClure / 500 Startups (2007)', '2026-07-10 17:55:46.360166+00', '2026-07-10 17:55:46.360166+00') on conflict do nothing;
insert into "frameworks" ("framework_id", "framework_code", "framework_name", "creator", "category", "what_it_is", "problem_it_solves", "stage_relevance", "industry_relevance", "how_alley_uses_it", "linked_root_cause_ids", "linked_intervention_ids", "source_reference", "created_at", "updated_at") values ('17', 'FW-017', 'Customer Journey Mapping', 'CX Design community', 'Go-To-Market', 'A visual representation of every interaction a customer has with the business from first awareness through purchase and beyond. Reveals friction points, gaps, and opportunities the founder cannot see from the inside.', 'Founders designing products and GTM from the inside out — based on what they think the customer experience is, not what it actually is.', '[2, 3, 4, 5]', '["all"]', 'Referenced in interventions for ''Confusing GTM with Marketing'' and ''Poor User Experience.'' Used in the diagnosis to probe whether founders understand their customer''s buying journey.', '["RC-073", "RC-074", "RC-075"]', '["INT-080", "INT-022", "INT-041"]', 'Founder Ally Intervention Library — Doc 8', '2026-07-10 17:55:46.360166+00', '2026-07-10 17:55:46.360166+00') on conflict do nothing;
insert into "frameworks" ("framework_id", "framework_code", "framework_name", "creator", "category", "what_it_is", "problem_it_solves", "stage_relevance", "industry_relevance", "how_alley_uses_it", "linked_root_cause_ids", "linked_intervention_ids", "source_reference", "created_at", "updated_at") values ('18', 'FW-018', 'Bowtie Model', 'Winning by Design', 'Go-To-Market', 'A revenue model that treats the customer lifecycle as a bowtie — acquisition and conversion on the left, expansion and advocacy on the right, with retention at the centre knot. Balances new customer growth with existing customer growth.', 'Founders treating revenue as a funnel that ends at purchase rather than a cycle that continues through retention and expansion.', '[4, 5, 6, 7]', '["saas", "services"]', 'Referenced in interventions for ''Over-Focusing on Acquisition'' and ''Losing Customers Costs More Than It Looks.'' Used in the SaaS and Services industry calibration layers.', '["RC-073", "RC-074", "RC-075"]', '["INT-059", "INT-022"]', 'Winning by Design / Jacco van der Kooij', '2026-07-10 17:55:46.360166+00', '2026-07-10 17:55:46.360166+00') on conflict do nothing;
insert into "frameworks" ("framework_id", "framework_code", "framework_name", "creator", "category", "what_it_is", "problem_it_solves", "stage_relevance", "industry_relevance", "how_alley_uses_it", "linked_root_cause_ids", "linked_intervention_ids", "source_reference", "created_at", "updated_at") values ('19', 'FW-019', 'Go-to-Market Strategy Canvas', 'Founder Ally / GoXL synthesis', 'Go-To-Market', 'A one-page framework that aligns ICP, value proposition, pricing, channels, sales motion, and success metrics into a single coherent GTM plan. Prevents the common mistake of treating GTM as just marketing.', 'Founders who build a marketing plan but not a GTM strategy — missing the commercial architecture needed to actually acquire and retain customers at scale.', '[2, 3, 4, 5]', '["all"]', 'Used in intervention for ''Confusing GTM with Marketing.'' The canvas is recommended as the first structured exercise before any marketing spend is committed.', '["RC-073", "RC-074", "RC-075"]', '["INT-022"]', 'Founder Ally Intervention Library — Doc 8', '2026-07-10 17:55:46.360166+00', '2026-07-10 17:55:46.360166+00') on conflict do nothing;
insert into "frameworks" ("framework_id", "framework_code", "framework_name", "creator", "category", "what_it_is", "problem_it_solves", "stage_relevance", "industry_relevance", "how_alley_uses_it", "linked_root_cause_ids", "linked_intervention_ids", "source_reference", "created_at", "updated_at") values ('20', 'FW-020', 'MEDDIC', 'Jack Napoli & Dick Dunkel', 'Sales & Revenue', 'A B2B sales qualification framework: Metrics (economic impact), Economic Buyer (who controls budget), Decision Criteria (how they decide), Decision Process (how the decision is made), Identify Pain (core problem), Champion (internal advocate). Ensures only qualified deals enter the pipeline.', 'Founders wasting sales time on unqualified leads that will never close. MEDDIC creates a structured basis for qualification that removes optimism bias.', '[3, 4, 5, 6]', '["all"]', 'Referenced in intervention for ''Weak Pipeline / No Deals.'' Used in the Question Bank for sales category probing questions about deal qualification and pipeline health.', '["RC-155", "RC-156", "RC-157"]', '[]', 'PTC Corporation sales methodology (1990s)', '2026-07-10 17:55:46.360166+00', '2026-07-10 17:55:46.360166+00') on conflict do nothing;
insert into "frameworks" ("framework_id", "framework_code", "framework_name", "creator", "category", "what_it_is", "problem_it_solves", "stage_relevance", "industry_relevance", "how_alley_uses_it", "linked_root_cause_ids", "linked_intervention_ids", "source_reference", "created_at", "updated_at") values ('21', 'FW-021', 'SPIN Selling', 'Neil Rackham', 'Sales & Revenue', 'A research-based sales methodology using four question types: Situation (context), Problem (pain points), Implication (consequences of the problem), Need-Payoff (value of solving it). Based on research into 35,000 sales calls.', 'Founders who pitch their product too early before understanding the customer''s problem deeply enough. SPIN replaces pitching with structured discovery.', '[2, 3, 4, 5]', '["all"]', 'Referenced in intervention for ''Inability to Close Deals.'' Used in the Question Bank to design probing questions that mirror the SPIN structure in the diagnosis flow.', '["RC-155", "RC-156", "RC-157"]', '["INT-006"]', 'SPIN Selling — Neil Rackham (1988)', '2026-07-10 17:55:46.360166+00', '2026-07-10 17:55:46.360166+00') on conflict do nothing;
insert into "frameworks" ("framework_id", "framework_code", "framework_name", "creator", "category", "what_it_is", "problem_it_solves", "stage_relevance", "industry_relevance", "how_alley_uses_it", "linked_root_cause_ids", "linked_intervention_ids", "source_reference", "created_at", "updated_at") values ('22', 'FW-022', 'Challenger Sale Framework', 'Matthew Dixon & Brent Adamson', 'Sales & Revenue', 'A sales approach where the salesperson teaches the customer something they do not know, tailors the message to their specific context, and takes control of the conversation. Based on research into what top salespeople do differently.', 'Founders who rely on relationship selling or product demonstrations without challenging the customer''s thinking. Works especially well for complex B2B sales.', '[3, 4, 5, 6]', '["all"]', 'Referenced in intervention for ''Inability to Close Deals.'' Recommended when the root cause is weak discovery skills or product-centric selling.', '["RC-155", "RC-156", "RC-157"]', '["INT-006"]', 'The Challenger Sale — Dixon & Adamson (2011)', '2026-07-10 17:55:46.360166+00', '2026-07-10 17:55:46.360166+00') on conflict do nothing;
insert into "frameworks" ("framework_id", "framework_code", "framework_name", "creator", "category", "what_it_is", "problem_it_solves", "stage_relevance", "industry_relevance", "how_alley_uses_it", "linked_root_cause_ids", "linked_intervention_ids", "source_reference", "created_at", "updated_at") values ('23', 'FW-023', 'Van Westendorp Price Sensitivity Meter', 'Hans van Westendorp', 'Sales & Revenue', 'A customer research method using four questions to establish acceptable price ranges: too cheap (quality concerns), cheap but acceptable, expensive but acceptable, too expensive. Creates price sensitivity curves from real customer data.', 'Founders pricing by gut feeling, cost-plus calculation, or competitor copying. Van Westendorp provides empirical data on what customers will actually pay.', '[1, 2, 3, 4, 5]', '["all"]', 'Referenced in intervention for ''Neglecting Pricing Strategy.'' Recommended when the root cause is ''pricing below market value'' or ''pricing without data.''', '["RC-155", "RC-156", "RC-157"]', '["INT-024"]', 'Hans van Westendorp (1976)', '2026-07-10 17:55:46.360166+00', '2026-07-10 17:55:46.360166+00') on conflict do nothing;
insert into "frameworks" ("framework_id", "framework_code", "framework_name", "creator", "category", "what_it_is", "problem_it_solves", "stage_relevance", "industry_relevance", "how_alley_uses_it", "linked_root_cause_ids", "linked_intervention_ids", "source_reference", "created_at", "updated_at") values ('24', 'FW-024', 'Value-Based Pricing Framework', 'Thomas Nagle', 'Sales & Revenue', 'A pricing methodology that sets prices based on the customer''s perceived value of the outcome — not the cost of production or what competitors charge. Requires understanding of the economic benefit the customer receives.', 'Founders chronically underpricing because they price on cost rather than value. Especially common in Indian market where cost-plus pricing is the default assumption.', '[2, 3, 4, 5, 6]', '["all"]', 'Referenced across multiple interventions for pricing root causes. The primary pricing framework recommended in Doc 9 (Industry Classification) for all 4 verticals.', '["RC-155", "RC-156", "RC-157"]', '["INT-024", "INT-057"]', 'The Strategy and Tactics of Pricing — Thomas Nagle', '2026-07-10 17:55:46.360166+00', '2026-07-10 17:55:46.360166+00') on conflict do nothing;
insert into "frameworks" ("framework_id", "framework_code", "framework_name", "creator", "category", "what_it_is", "problem_it_solves", "stage_relevance", "industry_relevance", "how_alley_uses_it", "linked_root_cause_ids", "linked_intervention_ids", "source_reference", "created_at", "updated_at") values ('25', 'FW-025', 'Customer Success Framework', 'Lincoln Murphy / Gainsight', 'Sales & Revenue', 'A structured approach to ensuring customers achieve their desired outcomes with the product. Covers onboarding, adoption, health monitoring, renewal, and expansion — treating customer success as a proactive function, not reactive support.', 'Founders treating customer success as customer support — reactive instead of proactive. Churn is almost always a customer success failure, not a product failure.', '[4, 5, 6, 7]', '["all"]', 'Referenced in interventions for ''Over-Discounting or Churn'' and ''Chasing New Customers vs Keeping Old Ones.'' Used heavily in the SaaS and Services industry calibration layers.', '["RC-155", "RC-156", "RC-157"]', '["INT-080", "INT-029"]', 'Customer Success — Nick Mehta et al. (2016)', '2026-07-10 17:55:46.360166+00', '2026-07-10 17:55:46.360166+00') on conflict do nothing;
insert into "frameworks" ("framework_id", "framework_code", "framework_name", "creator", "category", "what_it_is", "problem_it_solves", "stage_relevance", "industry_relevance", "how_alley_uses_it", "linked_root_cause_ids", "linked_intervention_ids", "source_reference", "created_at", "updated_at") values ('26', 'FW-026', 'SaaS Unit Economics Framework', 'SaaS industry standard', 'Sales & Revenue', 'A financial framework for measuring the health of a SaaS business through key metrics: Customer Acquisition Cost (CAC), Lifetime Value (LTV), LTV:CAC ratio, Gross Margin, Monthly Recurring Revenue (MRR), Net Revenue Retention (NRR), and Payback Period.', 'SaaS founders who cannot answer basic unit economics questions — growing revenue while destroying value. These metrics are the vital signs of a SaaS business.', '[3, 4, 5, 6, 7]', '["saas"]', 'Directly feeds the SaaS industry calibration in Doc 9. Used in the Question Bank for financial health probing. The red flag thresholds from this framework power the SaaS industry diagnostic adjustments.', '["RC-155", "RC-156", "RC-157"]', '["INT-027"]', 'SaaS industry standard / David Skok / OpenView Partners', '2026-07-10 17:55:46.360166+00', '2026-07-10 17:55:46.360166+00') on conflict do nothing;
insert into "frameworks" ("framework_id", "framework_code", "framework_name", "creator", "category", "what_it_is", "problem_it_solves", "stage_relevance", "industry_relevance", "how_alley_uses_it", "linked_root_cause_ids", "linked_intervention_ids", "source_reference", "created_at", "updated_at") values ('27', 'FW-027', 'Outbound Cadence Design', 'Sales Hacker / Outreach community', 'Sales & Revenue', 'A structured multi-touch outreach sequence that combines email, LinkedIn, phone, and content touches at specific intervals. Replaces random outreach with a systematic approach to building pipeline.', 'Founders who do one outreach attempt and give up when there is no response. Research shows most B2B deals require 8-12 touchpoints before a response.', '[2, 3, 4, 5]', '["all"]', 'Referenced in intervention for ''Weak Pipeline / No Deals.'' One of the three immediate next steps recommended for founders with a pipeline root cause.', '["RC-155", "RC-156", "RC-157"]', '["INT-005"]', 'Sales Hacker / Outreach.io best practices', '2026-07-10 17:55:46.360166+00', '2026-07-10 17:55:46.360166+00') on conflict do nothing;
insert into "frameworks" ("framework_id", "framework_code", "framework_name", "creator", "category", "what_it_is", "problem_it_solves", "stage_relevance", "industry_relevance", "how_alley_uses_it", "linked_root_cause_ids", "linked_intervention_ids", "source_reference", "created_at", "updated_at") values ('28', 'FW-028', 'Revenue Operations (RevOps) Framework', 'SiriusDecisions / Forrester', 'Sales & Revenue', 'A business function that integrates sales, marketing, customer success, and finance into one unified revenue system with shared data, processes, and accountability. Eliminates silos that cause revenue inefficiency.', 'Scaling companies where sales, marketing, and customer success work in silos with different data and different goals — causing revenue leakage and customer friction.', '[6, 7, 8]', '["all"]', 'Referenced in intervention for ''Too Many Revenue Streams to Track'' (Section 9.2 of Doc 8). Used in the Scaling & Operational Maturity category for Stage 6+ founders.', '["RC-155", "RC-156", "RC-157"]', '["INT-056"]', 'SiriusDecisions / Forrester Research', '2026-07-10 17:55:46.360166+00', '2026-07-10 17:55:46.360166+00') on conflict do nothing;
insert into "frameworks" ("framework_id", "framework_code", "framework_name", "creator", "category", "what_it_is", "problem_it_solves", "stage_relevance", "industry_relevance", "how_alley_uses_it", "linked_root_cause_ids", "linked_intervention_ids", "source_reference", "created_at", "updated_at") values ('29', 'FW-029', 'RICE Prioritisation Framework', 'Intercom', 'Product', 'A product prioritisation scoring model: Reach (how many users affected), Impact (how much it moves the needle), Confidence (how sure we are), divided by Effort (how much work). Creates an objective ranking of features and projects.', 'Founders who build features based on whoever asked loudest or what sounds exciting — without a systematic way to evaluate trade-offs.', '[3, 4, 5, 6, 7]', '["saas"]', 'Referenced in intervention for ''Feature Bloat.'' The primary prioritisation tool recommended when the root cause is ego-driven development or customer-pleasing behaviour.', '["RC-373", "RC-374", "RC-375"]', '["INT-012"]', 'Intercom — Sean McBride (2016)', '2026-07-10 17:55:46.360166+00', '2026-07-10 17:55:46.360166+00') on conflict do nothing;
insert into "frameworks" ("framework_id", "framework_code", "framework_name", "creator", "category", "what_it_is", "problem_it_solves", "stage_relevance", "industry_relevance", "how_alley_uses_it", "linked_root_cause_ids", "linked_intervention_ids", "source_reference", "created_at", "updated_at") values ('30', 'FW-030', 'Kano Model', 'Noriaki Kano', 'Product', 'A product development model that classifies features into three categories: Basic (must-haves that cause dissatisfaction if missing), Performance (the more the better), and Delight (unexpected features that create loyalty). Helps founders understand what actually drives customer satisfaction.', 'Founders adding features that do not improve satisfaction or remove features that customers take for granted. The Kano Model reveals the difference between what customers say they want and what actually makes them happy.', '[3, 4, 5, 6]', '["all"]', 'Referenced in interventions for ''Feature Bloat'' and ''Sacrificing User Needs for Monetisation.'' Used in the diagnosis to probe whether founders understand what their customers truly value.', '["RC-373", "RC-374", "RC-375"]', '["INT-043", "INT-012"]', 'Noriaki Kano (1984)', '2026-07-10 17:55:46.360166+00', '2026-07-10 17:55:46.360166+00') on conflict do nothing;
insert into "frameworks" ("framework_id", "framework_code", "framework_name", "creator", "category", "what_it_is", "problem_it_solves", "stage_relevance", "industry_relevance", "how_alley_uses_it", "linked_root_cause_ids", "linked_intervention_ids", "source_reference", "created_at", "updated_at") values ('31', 'FW-031', 'Sean Ellis PMF Survey', 'Sean Ellis', 'Product', 'A single-question survey to measure product-market fit: ''How would you feel if you could no longer use this product?'' If 40% or more answer ''Very disappointed,'' the product has reached PMF. Below 40% indicates the product has not yet found its fit.', 'Founders who believe they have product-market fit based on anecdotal evidence or their own excitement rather than systematic measurement.', '[3, 4, 5]', '["all"]', 'Referenced in intervention for ''Poor Product-Market Fit.'' Used in the Question Bank as a key metric-probing question for product category diagnosis.', '["RC-373", "RC-374", "RC-375"]', '[]', 'Sean Ellis / GrowthHackers (2009)', '2026-07-10 17:55:46.360166+00', '2026-07-10 17:55:46.360166+00') on conflict do nothing;
insert into "frameworks" ("framework_id", "framework_code", "framework_name", "creator", "category", "what_it_is", "problem_it_solves", "stage_relevance", "industry_relevance", "how_alley_uses_it", "linked_root_cause_ids", "linked_intervention_ids", "source_reference", "created_at", "updated_at") values ('32', 'FW-032', 'Continuous Discovery Habits', 'Teresa Torres', 'Product', 'A framework for embedding regular customer conversations into the product development process — weekly customer interviews, structured feedback synthesis, and opportunity mapping — rather than doing discovery as a one-time exercise.', 'Founders who do customer research once at the start and then build in isolation. Continuous discovery keeps the product aligned with evolving customer needs.', '[3, 4, 5, 6, 7]', '["all"]', 'Referenced in interventions for ''Lack of User Feedback Loop'' and ''Feature Bloat.'' One of the core frameworks for building a sustainable customer learning culture.', '["RC-373", "RC-374", "RC-375"]', '["INT-020", "INT-011"]', 'Continuous Discovery Habits — Teresa Torres (2021)', '2026-07-10 17:55:46.360166+00', '2026-07-10 17:55:46.360166+00') on conflict do nothing;
insert into "frameworks" ("framework_id", "framework_code", "framework_name", "creator", "category", "what_it_is", "problem_it_solves", "stage_relevance", "industry_relevance", "how_alley_uses_it", "linked_root_cause_ids", "linked_intervention_ids", "source_reference", "created_at", "updated_at") values ('33', 'FW-033', 'HEART Framework', 'Google', 'Product', 'A product metrics framework measuring five dimensions: Happiness (user satisfaction), Engagement (depth of interaction), Adoption (new user uptake), Retention (returning users), Task Success (completion of key actions). Provides a balanced view of product performance.', 'Founders measuring only revenue or user counts while ignoring engagement, satisfaction, and task completion — missing early warning signs of product-market fit erosion.', '[3, 4, 5, 6, 7]', '["saas"]', 'Referenced in interventions for ''Lack of User Feedback Loop'' and ''Poor User Experience.'' Used in the Question Bank to probe whether founders are tracking the right product metrics.', '["RC-373", "RC-374", "RC-375"]', '["INT-041", "INT-011"]', 'Google Ventures / Kerry Rodden (2010)', '2026-07-10 17:55:46.360166+00', '2026-07-10 17:55:46.360166+00') on conflict do nothing;
insert into "frameworks" ("framework_id", "framework_code", "framework_name", "creator", "category", "what_it_is", "problem_it_solves", "stage_relevance", "industry_relevance", "how_alley_uses_it", "linked_root_cause_ids", "linked_intervention_ids", "source_reference", "created_at", "updated_at") values ('34', 'FW-034', 'Minimum Viable Product (MVP)', 'Eric Ries', 'Product', 'The smallest version of a product that allows the team to collect the maximum amount of validated learning about customers with the least effort. Not a cheap product — a learning instrument.', 'Founders building complete products before validating assumptions. The MVP shifts the question from ''Can we build it?'' to ''Should we build it?''', '[1, 2, 3]', '["all"]', 'One of the most fundamental frameworks in the Founder Ally library. Referenced across multiple categories. Used as the primary intervention for perfectionism and over-engineering root causes.', '["RC-373", "RC-374", "RC-375"]', '["INT-040"]', 'The Lean Startup — Eric Ries (2011)', '2026-07-10 17:55:46.360166+00', '2026-07-10 17:55:46.360166+00') on conflict do nothing;
insert into "frameworks" ("framework_id", "framework_code", "framework_name", "creator", "category", "what_it_is", "problem_it_solves", "stage_relevance", "industry_relevance", "how_alley_uses_it", "linked_root_cause_ids", "linked_intervention_ids", "source_reference", "created_at", "updated_at") values ('35', 'FW-035', 'Product Vision Board', 'Roman Pichler', 'Product', 'A one-page strategic tool that aligns the team around target users, customer needs, product features, and business goals. Creates a shared understanding of where the product is going and why.', 'Founders and teams who are building without a shared product direction — everyone has a different idea of where the product should go next.', '[2, 3, 4, 5, 6]', '["all"]', 'Referenced in intervention for ''No Clear Product Vision.'' Recommended as the first tool when the root cause is reactive development or vision confusion.', '["RC-373", "RC-374", "RC-375"]', '["INT-042"]', 'Roman Pichler (2012)', '2026-07-10 17:55:46.360166+00', '2026-07-10 17:55:46.360166+00') on conflict do nothing;
insert into "frameworks" ("framework_id", "framework_code", "framework_name", "creator", "category", "what_it_is", "problem_it_solves", "stage_relevance", "industry_relevance", "how_alley_uses_it", "linked_root_cause_ids", "linked_intervention_ids", "source_reference", "created_at", "updated_at") values ('36', 'FW-036', 'Now-Next-Later Roadmap', 'Janna Basler / Product community', 'Product', 'A simple roadmap format that organises work into three horizons — what is being built now, what comes next, and what is planned for later — without false precision about dates or specific features far in the future.', 'Founders who either have no roadmap or have overly detailed roadmaps that become obsolete within weeks. The Now-Next-Later format balances structure with flexibility.', '[2, 3, 4, 5, 6]', '["all"]', 'Referenced in intervention for ''No Clear Product Vision.'' Provides the practical structure for managing product direction without becoming rigidly committed to a long-term plan that will inevitably change.', '["RC-373", "RC-374", "RC-375"]', '["INT-012"]', 'Janna Basler / ProductPlan', '2026-07-10 17:55:46.360166+00', '2026-07-10 17:55:46.360166+00') on conflict do nothing;
insert into "frameworks" ("framework_id", "framework_code", "framework_name", "creator", "category", "what_it_is", "problem_it_solves", "stage_relevance", "industry_relevance", "how_alley_uses_it", "linked_root_cause_ids", "linked_intervention_ids", "source_reference", "created_at", "updated_at") values ('37', 'FW-037', 'Product-Market Fit Pyramid', 'Dan Olsen', 'Product', 'A five-layer hierarchy for achieving PMF: Target customer → Underserved needs → Value proposition → Feature set → UX. Each layer must be solved before the one above it. Provides a structured path to finding fit.', 'Founders who are trying to find PMF by changing features without understanding which layer of the pyramid is actually broken.', '[2, 3, 4, 5]', '["all"]', 'Referenced in intervention for ''Poor Product-Market Fit.'' Used in the diagnosis to identify which layer of the PMF pyramid is causing the fit problem.', '["RC-373", "RC-374", "RC-375"]', '["INT-043"]', 'The Lean Product Playbook — Dan Olsen (2015)', '2026-07-10 17:55:46.360166+00', '2026-07-10 17:55:46.360166+00') on conflict do nothing;
insert into "frameworks" ("framework_id", "framework_code", "framework_name", "creator", "category", "what_it_is", "problem_it_solves", "stage_relevance", "industry_relevance", "how_alley_uses_it", "linked_root_cause_ids", "linked_intervention_ids", "source_reference", "created_at", "updated_at") values ('38', 'FW-038', 'Delegation Ladder (7 Levels)', 'Management 3.0 community', 'Team & Leadership', 'A framework defining seven levels of delegation from ''Do as I say'' through ''Decide and don''t report.'' Each level gives more autonomy and ownership to the team member. Helps founders match the right delegation level to each person and task.', 'Founders who either micro-manage everything or delegate without structure — both leading to poor outcomes. The ladder makes delegation a conscious, scalable practice.', '[3, 4, 5, 6, 7]', '["all"]', 'Referenced in intervention for ''Hero Syndrome / Founder Does Everything.'' One of the three immediate next steps for delegation root causes.', '["RC-225", "RC-226", "RC-227"]', '["INT-007"]', 'Management 3.0 — Jurgen Appelo', '2026-07-10 17:55:46.360166+00', '2026-07-10 17:55:46.360166+00') on conflict do nothing;
insert into "frameworks" ("framework_id", "framework_code", "framework_name", "creator", "category", "what_it_is", "problem_it_solves", "stage_relevance", "industry_relevance", "how_alley_uses_it", "linked_root_cause_ids", "linked_intervention_ids", "source_reference", "created_at", "updated_at") values ('39', 'FW-039', 'WHO Hiring Method', 'Geoff Smart & Randy Street', 'Team & Leadership', 'A structured hiring methodology using scorecards (defining outcomes before hiring), structured behavioural interviews (A-Method), and deep reference checks. Replaces gut-feel hiring with evidence-based selection.', 'Founders making hiring mistakes because they rely on interviews without a structured evaluation process. Bad hires at early stage can be existential.', '[3, 4, 5, 6, 7]', '["all"]', 'Referenced in intervention for ''Poor Hiring Practices.'' One of the primary recommended frameworks when the root cause is urgency bias or gut-feel hiring.', '["RC-225", "RC-226", "RC-227"]', '["INT-033", "INT-031"]', 'WHO: The A Method for Hiring — Geoff Smart & Randy', '2026-07-10 17:55:46.360166+00', '2026-07-10 17:55:46.360166+00') on conflict do nothing;
insert into "frameworks" ("framework_id", "framework_code", "framework_name", "creator", "category", "what_it_is", "problem_it_solves", "stage_relevance", "industry_relevance", "how_alley_uses_it", "linked_root_cause_ids", "linked_intervention_ids", "source_reference", "created_at", "updated_at") values ('40', 'FW-040', 'Five Dysfunctions of a Team', 'Patrick Lencioni', 'Team & Leadership', 'A model identifying the five root causes of team dysfunction in hierarchy: absence of trust, fear of conflict, lack of commitment, avoidance of accountability, and inattention to results. Each dysfunction builds on the one below it.', 'Teams that appear functional on the surface but are plagued by unspoken conflicts, lack of commitment, and poor accountability. The model reveals which dysfunction is the actual root cause.', '[3, 4, 5, 6, 7]', '["all"]', 'Referenced across multiple team root causes. Used in the diagnosis to probe co-founder conflicts, team culture problems, and accountability gaps.', '["RC-225", "RC-226", "RC-227"]', '["INT-089", "INT-030"]', 'The Five Dysfunctions of a Team — Patrick Lencioni', '2026-07-10 17:55:46.360166+00', '2026-07-10 17:55:46.360166+00') on conflict do nothing;
insert into "frameworks" ("framework_id", "framework_code", "framework_name", "creator", "category", "what_it_is", "problem_it_solves", "stage_relevance", "industry_relevance", "how_alley_uses_it", "linked_root_cause_ids", "linked_intervention_ids", "source_reference", "created_at", "updated_at") values ('41', 'FW-041', 'EOS — Entrepreneurial Operating System', 'Gino Wickman', 'Team & Leadership', 'A complete business operating system built around six components: Vision, People, Data, Issues, Process, and Traction. Provides a practical system for running a company through Level 10 Meetings, Rocks (quarterly priorities), and Scorecards.', 'Founders who are growing but lack the operational structure to keep everyone aligned and accountable. EOS translates vision into daily execution.', '[4, 5, 6, 7, 8]', '["all"]', 'Referenced in interventions for ''Hero Syndrome,'' ''No SOPs,'' and ''No Processes.'' One of the most comprehensive operating system frameworks in the Founder Ally library.', '["RC-225", "RC-226", "RC-227"]', '["INT-050", "INT-007", "INT-093"]', 'Traction — Gino Wickman (2011)', '2026-07-10 17:55:46.360166+00', '2026-07-10 17:55:46.360166+00') on conflict do nothing;
insert into "frameworks" ("framework_id", "framework_code", "framework_name", "creator", "category", "what_it_is", "problem_it_solves", "stage_relevance", "industry_relevance", "how_alley_uses_it", "linked_root_cause_ids", "linked_intervention_ids", "source_reference", "created_at", "updated_at") values ('42', 'FW-042', 'Situational Leadership II', 'Ken Blanchard', 'Team & Leadership', 'A leadership model that matches leadership style (directing, coaching, supporting, delegating) to each team member''s development level (competence and commitment). Recognises that the right leadership approach depends on who you are leading and in what context.', 'Leaders who apply the same management style to every team member regardless of their experience or confidence level — leading to under-development of high-potential people and over-support of capable ones.', '[4, 5, 6, 7, 8]', '["all"]', 'Referenced in interventions for ''Leading Through Managers Instead of Directly'' and ''Trust Enough to Let Go.'' Used in the scaling section for founders transitioning to executive leadership.', '["RC-225", "RC-226", "RC-227"]', '["INT-055", "INT-088"]', 'Leadership and the One Minute Manager — Blanchard et', '2026-07-10 17:55:46.360166+00', '2026-07-10 17:55:46.360166+00') on conflict do nothing;
insert into "frameworks" ("framework_id", "framework_code", "framework_name", "creator", "category", "what_it_is", "problem_it_solves", "stage_relevance", "industry_relevance", "how_alley_uses_it", "linked_root_cause_ids", "linked_intervention_ids", "source_reference", "created_at", "updated_at") values ('43', 'FW-043', 'RACI Matrix', 'Project management standard', 'Team & Leadership', 'A responsibility assignment matrix that defines who is Responsible (does the work), Accountable (owns the outcome), Consulted (provides input), and Informed (receives updates) for every major task or decision.', 'Teams and organisations where nobody knows who is responsible for what — leading to duplication, gaps, and finger-pointing when things go wrong.', '[3, 4, 5, 6, 7, 8]', '["all"]', 'One of the most frequently referenced frameworks in the Founder Ally library. Used across Team, Operations, and Scaling categories whenever role ambiguity or accountability gaps are the root cause.', '["RC-225", "RC-226", "RC-227"]', '["INT-090", "INT-089", "INT-076"]', 'Project management standard — widely attributed to', '2026-07-10 17:55:46.360166+00', '2026-07-10 17:55:46.360166+00') on conflict do nothing;
insert into "frameworks" ("framework_id", "framework_code", "framework_name", "creator", "category", "what_it_is", "problem_it_solves", "stage_relevance", "industry_relevance", "how_alley_uses_it", "linked_root_cause_ids", "linked_intervention_ids", "source_reference", "created_at", "updated_at") values ('44', 'FW-044', '9-Box Talent Matrix', 'McKinsey / GE', 'Team & Leadership', 'A talent assessment tool that plots employees on a 3x3 grid of performance (current results) versus potential (future capability). Creates a visual map of the talent portfolio and guides development, succession, and retention decisions.', 'Leaders who make talent decisions based on recency bias or personal relationships rather than a structured assessment of performance and potential.', '[5, 6, 7, 8]', '["all"]', 'Referenced in intervention for ''No Plan for Who Comes Next.'' Used in the People Management Complexity section for scaling companies.', '["RC-225", "RC-226", "RC-227"]', '["INT-070"]', 'McKinsey & Company / GE (1970s)', '2026-07-10 17:55:46.360166+00', '2026-07-10 17:55:46.360166+00') on conflict do nothing;
insert into "frameworks" ("framework_id", "framework_code", "framework_name", "creator", "category", "what_it_is", "problem_it_solves", "stage_relevance", "industry_relevance", "how_alley_uses_it", "linked_root_cause_ids", "linked_intervention_ids", "source_reference", "created_at", "updated_at") values ('45', 'FW-045', 'Psychological Safety Framework', 'Amy Edmondson', 'Team & Leadership', 'A research-based model for creating team environments where people can speak up, take risks, and challenge ideas without fear of punishment or embarrassment. Based on research showing psychological safety is the top predictor of team performance.', 'Teams where people hold back important information, avoid conflict, and pretend agreement — leading to poor decisions and hidden problems that surface too late.', '[3, 4, 5, 6, 7, 8]', '["all"]', 'Referenced in interventions for ''Cultural or Communication Problems'' and ''Office Politics.'' Used in the Founder Behaviour document as a key principle for the empathy framework.', '["RC-225", "RC-226", "RC-227"]', '["INT-074", "INT-008"]', 'The Fearless Organisation — Amy Edmondson (2018)', '2026-07-10 17:55:46.360166+00', '2026-07-10 17:55:46.360166+00') on conflict do nothing;
insert into "frameworks" ("framework_id", "framework_code", "framework_name", "creator", "category", "what_it_is", "problem_it_solves", "stage_relevance", "industry_relevance", "how_alley_uses_it", "linked_root_cause_ids", "linked_intervention_ids", "source_reference", "created_at", "updated_at") values ('46', 'FW-046', 'Leadership Pipeline Model', 'Charan, Drotter & Noel', 'Team & Leadership', 'A model describing the six passages leaders must navigate from individual contributor to enterprise leader — each requiring new skills, time applications, and work values. Helps organisations develop leaders systematically at each passage.', 'Companies that promote high performers into leadership roles without preparing them for the fundamentally different work of leading others. The model identifies which leadership passage is causing the gap.', '[5, 6, 7, 8]', '["all"]', 'Referenced in interventions for ''New Managers Never Actually Trained'' and ''From Doing the Work to Leading the Company.'' Used heavily in the Scaling section.', '["RC-225", "RC-226", "RC-227"]', '["INT-075"]', 'The Leadership Pipeline — Charan, Drotter & Noel', '2026-07-10 17:55:46.360166+00', '2026-07-10 17:55:46.360166+00') on conflict do nothing;
insert into "frameworks" ("framework_id", "framework_code", "framework_name", "creator", "category", "what_it_is", "problem_it_solves", "stage_relevance", "industry_relevance", "how_alley_uses_it", "linked_root_cause_ids", "linked_intervention_ids", "source_reference", "created_at", "updated_at") values ('47', 'FW-047', 'Sequoia Capital Story Framework', 'Sequoia Capital', 'Fundraising', 'A pitch narrative framework covering: company purpose, problem, solution, why now, market size, competition, product, team, business model, and traction. Used by Sequoia to evaluate and improve founder pitches.', 'Founders who have strong businesses but tell weak investment stories. The framework organises the narrative in the order that maximises investor conviction.', '[3, 4, 5, 6]', '["all"]', 'Referenced in intervention for ''Unable to Raise Capital.'' The primary pitch narrative framework recommended when the root cause is weak storytelling or poor investor narrative.', '["RC-297", "RC-298", "RC-299"]', '["INT-062", "INT-030", "INT-091"]', 'Sequoia Capital internal framework / widely published', '2026-07-10 17:55:46.360166+00', '2026-07-10 17:55:46.360166+00') on conflict do nothing;
insert into "frameworks" ("framework_id", "framework_code", "framework_name", "creator", "category", "what_it_is", "problem_it_solves", "stage_relevance", "industry_relevance", "how_alley_uses_it", "linked_root_cause_ids", "linked_intervention_ids", "source_reference", "created_at", "updated_at") values ('48', 'FW-048', 'Guy Kawasaki 10-20-30 Rule', 'Guy Kawasaki', 'Fundraising', 'A pitch presentation guideline: 10 slides maximum, 20 minutes maximum, 30-point minimum font size. Forces founders to distil their story to what truly matters and present it in a way investors can actually absorb.', 'Founders with 40-slide pitch decks full of small text that investors cannot follow. Simplicity and clarity in pitch decks correlate strongly with investor engagement.', '[3, 4, 5, 6]', '["all"]', 'Referenced in intervention for ''Weak Pitch Deck.'' One of the first recommended fixes when the root cause is information overload or unfocused pitch narrative.', '["RC-297", "RC-298", "RC-299"]', '["INT-010"]', 'The Art of the Start — Guy Kawasaki (2004)', '2026-07-10 17:55:46.360166+00', '2026-07-10 17:55:46.360166+00') on conflict do nothing;
insert into "frameworks" ("framework_id", "framework_code", "framework_name", "creator", "category", "what_it_is", "problem_it_solves", "stage_relevance", "industry_relevance", "how_alley_uses_it", "linked_root_cause_ids", "linked_intervention_ids", "source_reference", "created_at", "updated_at") values ('49', 'FW-049', 'Milestone-Based Fundraising Framework', 'Venture capital standard', 'Fundraising', 'A fundraising approach where the founder raises only enough capital to reach the next major value-inflection milestone — rather than raising the maximum possible or the minimum to survive. Each raise is sized to the next proof point.', 'Founders who raise too little (run out before proving the next milestone) or too much (take unnecessary dilution before the business is ready to deploy capital efficiently).', '[2, 3, 4, 5]', '["all"]', 'Referenced in interventions for ''Raising Too Little Capital'' and ''Raising Too Much Too Early.'' The core framework for rational fundraising strategy.', '["RC-297", "RC-298", "RC-299"]', '["INT-009"]', 'Venture capital best practice / Fred Wilson / A16Z', '2026-07-10 17:55:46.360166+00', '2026-07-10 17:55:46.360166+00') on conflict do nothing;
insert into "frameworks" ("framework_id", "framework_code", "framework_name", "creator", "category", "what_it_is", "problem_it_solves", "stage_relevance", "industry_relevance", "how_alley_uses_it", "linked_root_cause_ids", "linked_intervention_ids", "source_reference", "created_at", "updated_at") values ('50', 'FW-050', 'Investor Fit Scorecard', 'Founder Ally / GoXL synthesis', 'Fundraising', 'A structured evaluation framework for assessing investor fit before taking meetings. Scores investors on stage preference, sector expertise, value-add beyond capital, decision speed, and founder reputation.', 'Founders who take meetings with every investor who responds and waste months pitching the wrong people. Investor fit is as important as investor interest.', '[3, 4, 5, 6]', '["all"]', 'Referenced in intervention for ''Wrong Investor Fit.'' Recommended as the first step before any fundraising outreach begins.', '["RC-297", "RC-298", "RC-299"]', '["INT-036"]', 'Founder Ally Intervention Library — Doc 8', '2026-07-10 17:55:46.360166+00', '2026-07-10 17:55:46.360166+00') on conflict do nothing;
insert into "frameworks" ("framework_id", "framework_code", "framework_name", "creator", "category", "what_it_is", "problem_it_solves", "stage_relevance", "industry_relevance", "how_alley_uses_it", "linked_root_cause_ids", "linked_intervention_ids", "source_reference", "created_at", "updated_at") values ('51', 'FW-051', 'Bottom-Up Market Sizing', 'Venture capital standard', 'Fundraising', 'A market sizing methodology that builds TAM, SAM, and SOM from the ground up using unit economics — number of potential customers times average contract value — rather than citing top-down industry reports.', 'Founders citing vague top-down TAM numbers like ''the Indian EdTech market is worth $10 billion'' without any logic connecting that number to their actual opportunity.', '[2, 3, 4, 5]', '["all"]', 'Referenced in intervention for ''Weak Pitch Deck.'' Taught as part of the pitch narrative framework. The foundation of a credible investor story.', '["RC-297", "RC-298", "RC-299"]', '["INT-010"]', 'Venture capital standard / widely attributed', '2026-07-10 17:57:13.082473+00', '2026-07-10 17:57:13.082473+00') on conflict do nothing;
insert into "frameworks" ("framework_id", "framework_code", "framework_name", "creator", "category", "what_it_is", "problem_it_solves", "stage_relevance", "industry_relevance", "how_alley_uses_it", "linked_root_cause_ids", "linked_intervention_ids", "source_reference", "created_at", "updated_at") values ('52', 'FW-052', 'Monthly Investor Update Framework', 'Founder Ally / GoXL synthesis', 'Fundraising', 'A structured format for monthly investor communications covering: key metrics against targets, milestones achieved, current challenges, specific asks, and financial update. Builds trust and opens doors for additional support.', 'Founders who only communicate with investors when raising again — destroying trust and missing opportunities for introductions, advice, and support.', '[4, 5, 6, 7, 8]', '["all"]', 'Referenced in intervention for ''Poor Investor Management.'' One of the three immediate next steps when the root cause is reactive investor relations.', '["RC-297", "RC-298", "RC-299"]', '["INT-091", "INT-037"]', 'Founder Ally Intervention Library — Doc 8', '2026-07-10 17:57:13.082473+00', '2026-07-10 17:57:13.082473+00') on conflict do nothing;
insert into "frameworks" ("framework_id", "framework_code", "framework_name", "creator", "category", "what_it_is", "problem_it_solves", "stage_relevance", "industry_relevance", "how_alley_uses_it", "linked_root_cause_ids", "linked_intervention_ids", "source_reference", "created_at", "updated_at") values ('53', 'FW-053', 'OKRs — Objectives and Key Results', 'Andy Grove / John Doerr', 'Operations & Systems', 'A goal-setting framework that connects ambitious qualitative objectives to 3-5 measurable key results. Creates alignment from company level to individual level. Objectives set direction; key results measure progress.', 'Founders and organisations that set vague goals like ''grow the business'' without measurable outcomes. OKRs replace ambiguity with accountability.', '[4, 5, 6, 7, 8]', '["all"]', 'One of the most referenced frameworks in the entire Founder Ally library. Used in interventions for ''No Metrics or KPIs'' and ''Founder as Bottleneck.'' Also referenced in cross-category branching rules.', '["RC-445", "RC-446", "RC-447"]', '["INT-069", "INT-095"]', 'Measure What Matters — John Doerr (2018)', '2026-07-10 17:57:13.082473+00', '2026-07-10 17:57:13.082473+00') on conflict do nothing;
insert into "frameworks" ("framework_id", "framework_code", "framework_name", "creator", "category", "what_it_is", "problem_it_solves", "stage_relevance", "industry_relevance", "how_alley_uses_it", "linked_root_cause_ids", "linked_intervention_ids", "source_reference", "created_at", "updated_at") values ('54', 'FW-054', '13-Week Cash Flow Forecast', 'Financial management standard', 'Operations & Systems', 'A rolling weekly cash flow projection covering the next 13 weeks (one quarter). Tracks expected cash inflows and outflows week by week to identify liquidity risks before they become crises.', 'Founders who manage cash by checking the bank balance rather than projecting forward. 13 weeks gives enough visibility to respond to problems before they become existential.', '[3, 4, 5, 6, 7, 8]', '["all"]', 'Referenced in multiple interventions across Operations and Financial categories. One of the first tools recommended when cash flow or financial disorganisation is the root cause.', '["RC-445", "RC-446", "RC-447"]', '["INT-039", "INT-062", "INT-094"]', 'Financial management best practice / widely attributed', '2026-07-10 17:57:13.082473+00', '2026-07-10 17:57:13.082473+00') on conflict do nothing;
insert into "frameworks" ("framework_id", "framework_code", "framework_name", "creator", "category", "what_it_is", "problem_it_solves", "stage_relevance", "industry_relevance", "how_alley_uses_it", "linked_root_cause_ids", "linked_intervention_ids", "source_reference", "created_at", "updated_at") values ('55', 'FW-055', 'Zero-Based Budgeting', 'Peter Pyhrr', 'Operations & Systems', 'A budgeting approach where every expense must be justified from scratch for each period — rather than starting from last period''s budget and making adjustments. Forces discipline around every line of spending.', 'Founders and scaling companies where spending grows by default rather than by decision. ZBB creates deliberate cost discipline instead of incremental cost drift.', '[4, 5, 6, 7, 8]', '["all"]', 'Referenced in interventions for ''Financial Disorganisation'' and ''Spending Grows Faster Than Control.'' Used in the Scaling & Operational Maturity section.', '["RC-445", "RC-446", "RC-447"]', '["INT-039", "INT-094", "INT-061"]', 'Zero-Base Budgeting — Peter Pyhrr (1973)', '2026-07-10 17:57:13.082473+00', '2026-07-10 17:57:13.082473+00') on conflict do nothing;
insert into "frameworks" ("framework_id", "framework_code", "framework_name", "creator", "category", "what_it_is", "problem_it_solves", "stage_relevance", "industry_relevance", "how_alley_uses_it", "linked_root_cause_ids", "linked_intervention_ids", "source_reference", "created_at", "updated_at") values ('56', 'FW-056', 'Standard Operating Procedures (SOP) Framework', 'Operations management standard', 'Operations & Systems', 'A documentation system for recurring processes — step-by-step instructions that allow any trained person to complete the task consistently to the required standard. Converts founder knowledge into organisational knowledge.', 'Founders and teams where critical knowledge lives only in people''s heads. When key people leave or scale creates volume, undocumented processes break.', '[3, 4, 5, 6, 7, 8]', '["all"]', 'Referenced in interventions for ''No SOPs / Operational Chaos'' and ''Nobody Wrote Anything Down.'' One of the most frequently recommended immediate actions for operations root causes.', '["RC-445", "RC-446", "RC-447"]', '["INT-046", "INT-013"]', 'Operations management standard / widely attributed', '2026-07-10 17:57:13.082473+00', '2026-07-10 17:57:13.082473+00') on conflict do nothing;
insert into "frameworks" ("framework_id", "framework_code", "framework_name", "creator", "category", "what_it_is", "problem_it_solves", "stage_relevance", "industry_relevance", "how_alley_uses_it", "linked_root_cause_ids", "linked_intervention_ids", "source_reference", "created_at", "updated_at") values ('57', 'FW-057', 'North Star Metric Framework', 'Sean Ellis / growth community', 'Operations & Systems', 'A framework for identifying the single metric that best captures the core value the product delivers to customers — and aligning the entire organisation around growing it. The North Star prevents the fragmentation that comes from optimising multiple competing metrics.', 'Organisations where different teams optimise different metrics that are not connected to real customer value. Revenue can grow while customer value erodes — the North Star prevents this disconnect.', '[3, 4, 5, 6, 7]', '["all"]', 'Referenced in interventions for ''No Metrics or KPIs'' and ''Over-Focusing on Acquisition.'' One of the key strategic alignment tools in the Founder Ally framework library.', '["RC-445", "RC-446", "RC-447"]', '["INT-026", "INT-095", "INT-042"]', 'Sean Ellis / GrowthHackers community', '2026-07-10 17:57:13.082473+00', '2026-07-10 17:57:13.082473+00') on conflict do nothing;
insert into "frameworks" ("framework_id", "framework_code", "framework_name", "creator", "category", "what_it_is", "problem_it_solves", "stage_relevance", "industry_relevance", "how_alley_uses_it", "linked_root_cause_ids", "linked_intervention_ids", "source_reference", "created_at", "updated_at") values ('58', 'FW-058', 'Business Process Mapping (BPM)', 'Operations management standard', 'Operations & Systems', 'A method for visually documenting how work flows through an organisation — identifying inputs, outputs, decisions, and handoffs. Reveals inefficiencies, bottlenecks, and gaps that are invisible in verbal descriptions.', 'Founders who cannot identify why processes keep breaking as the team grows. Process mapping makes the invisible visible.', '[4, 5, 6, 7, 8]', '["all"]', 'Referenced in interventions for ''Simple Processes Collapse Under Growth'' and ''No Processes or Ad-Hoc Operations.'' The foundational tool for operational improvement.', '["RC-445", "RC-446", "RC-447"]', '["INT-046"]', 'Operations management standard / widely attributed', '2026-07-10 17:57:13.082473+00', '2026-07-10 17:57:13.082473+00') on conflict do nothing;
insert into "frameworks" ("framework_id", "framework_code", "framework_name", "creator", "category", "what_it_is", "problem_it_solves", "stage_relevance", "industry_relevance", "how_alley_uses_it", "linked_root_cause_ids", "linked_intervention_ids", "source_reference", "created_at", "updated_at") values ('59', 'FW-059', 'Burn Multiple', 'David Sacks', 'Operations & Systems', 'A capital efficiency metric that measures how much cash a company burns for every dollar of new ARR added. Burn Multiple = Net Burn / Net New ARR. Lower is better — a Burn Multiple above 2 in early stage is a warning sign.', 'SaaS founders who are growing revenue but not tracking whether they are burning capital efficiently. High burn multiples signal that growth is being bought, not built.', '[4, 5, 6, 7]', '["saas"]', 'Referenced in interventions for ''Spending Grows Faster Than Control'' and ''Financial Disorganisation.'' Used in the SaaS industry calibration layer as a key red flag metric.', '["RC-445", "RC-446", "RC-447"]', '["INT-061", "INT-035"]', 'David Sacks / Craft Ventures (2020)', '2026-07-10 17:57:13.082473+00', '2026-07-10 17:57:13.082473+00') on conflict do nothing;
insert into "frameworks" ("framework_id", "framework_code", "framework_name", "creator", "category", "what_it_is", "problem_it_solves", "stage_relevance", "industry_relevance", "how_alley_uses_it", "linked_root_cause_ids", "linked_intervention_ids", "source_reference", "created_at", "updated_at") values ('60', 'FW-060', 'Cognitive Restructuring', 'Aaron Beck / CBT', 'Founder Psychology', 'A psychological technique for identifying and challenging distorted thinking patterns — catastrophising, all-or-nothing thinking, mind-reading — and replacing them with evidence-based alternatives. From Cognitive Behavioural Therapy.', 'Founders whose decision-making and wellbeing are being undermined by distorted thinking patterns they cannot see. Cognitive restructuring creates the awareness to interrupt these patterns.', '[1, 2, 3, 4, 5, 6, 7, 8]', '["all"]', 'Referenced in intervention for ''Fear of Failure / Imposter Syndrome.'' Used as the primary psychological intervention when the root cause is identity-level thinking distortion.', '["RC-517", "RC-518", "RC-519"]', '["INT-014"]', 'Cognitive Therapy of Depression — Aaron Beck (1979)', '2026-07-10 17:57:13.082473+00', '2026-07-10 17:57:13.082473+00') on conflict do nothing;
insert into "frameworks" ("framework_id", "framework_code", "framework_name", "creator", "category", "what_it_is", "problem_it_solves", "stage_relevance", "industry_relevance", "how_alley_uses_it", "linked_root_cause_ids", "linked_intervention_ids", "source_reference", "created_at", "updated_at") values ('61', 'FW-061', 'Premortem Analysis', 'Gary Klein', 'Founder Psychology', 'A decision-making technique where, before a major decision, the team imagines the decision has already failed and works backwards to identify why. Surfaces blind spots and risks that forward-looking planning misses.', 'Founders who make major decisions while overconfident in their success. The premortem uses prospective hindsight to identify failure modes before they occur.', '[2, 3, 4, 5, 6, 7, 8]', '["all"]', 'Referenced in interventions for ''Decision Paralysis / Poor Decision Quality'' and ''Failure to Pivot.'' Also referenced in the Agent Interpretation Table as a probing method for blind spots.', '["RC-517", "RC-518", "RC-519"]', '["INT-002", "INT-016"]', 'Sources of Power — Gary Klein (1998)', '2026-07-10 17:57:13.082473+00', '2026-07-10 17:57:13.082473+00') on conflict do nothing;
insert into "frameworks" ("framework_id", "framework_code", "framework_name", "creator", "category", "what_it_is", "problem_it_solves", "stage_relevance", "industry_relevance", "how_alley_uses_it", "linked_root_cause_ids", "linked_intervention_ids", "source_reference", "created_at", "updated_at") values ('62', 'FW-062', 'Decision Journal', 'Shane Parrish / Farnam Street', 'Founder Psychology', 'A personal discipline where the founder records every major decision — the context, the reasoning, the expected outcome, and the alternatives considered — then reviews these entries over time to identify patterns in decision quality.', 'Founders who do not learn from their decisions because they do not record them. The decision journal creates a feedback loop between decisions and outcomes.', '[1, 2, 3, 4, 5, 6, 7, 8]', '["all"]', 'Referenced in interventions for ''Decision Paralysis'' and ''Weak Governance or Oversight.'' One of the three immediate next steps when decision-making quality is the root cause.', '["RC-517", "RC-518", "RC-519"]', '["INT-054", "INT-016", "INT-034"]', 'Shane Parrish / Farnam Street (widely attributed)', '2026-07-10 17:57:13.082473+00', '2026-07-10 17:57:13.082473+00') on conflict do nothing;
insert into "frameworks" ("framework_id", "framework_code", "framework_name", "creator", "category", "what_it_is", "problem_it_solves", "stage_relevance", "industry_relevance", "how_alley_uses_it", "linked_root_cause_ids", "linked_intervention_ids", "source_reference", "created_at", "updated_at") values ('63', 'FW-063', 'Red-Teaming', 'Military / Intelligence community', 'Founder Psychology', 'A structured adversarial analysis technique where one person or team is given the explicit role of challenging a decision, plan, or strategy — arguing against it as forcefully as possible to surface weaknesses before commitment.', 'Founders who surround themselves with people who agree with them. Red-teaming introduces legitimate challenge into the decision process before it is too late to change course.', '[2, 3, 4, 5, 6, 7, 8]', '["all"]', 'Referenced in intervention for ''Decision Paralysis / Poor Decision Quality.'' Used alongside the Premortem as a complementary decision quality tool.', '["RC-517", "RC-518", "RC-519"]', '["INT-016"]', 'Military and intelligence community standard / widely', '2026-07-10 17:57:13.082473+00', '2026-07-10 17:57:13.082473+00') on conflict do nothing;
insert into "frameworks" ("framework_id", "framework_code", "framework_name", "creator", "category", "what_it_is", "problem_it_solves", "stage_relevance", "industry_relevance", "how_alley_uses_it", "linked_root_cause_ids", "linked_intervention_ids", "source_reference", "created_at", "updated_at") values ('64', 'FW-064', 'Two-Way Door Framework', 'Jeff Bezos / Amazon', 'Founder Psychology', 'A decision classification framework that separates reversible decisions (two-way doors — easy to change) from irreversible decisions (one-way doors — very hard to change). Encourages speed on reversible decisions and caution on irreversible ones.', 'Founders who apply the same level of analysis to every decision — spending too long on small reversible choices and not enough time on major irreversible ones. Creates decision velocity without recklessness.', '[1, 2, 3, 4, 5, 6, 7, 8]', '["all"]', 'Referenced in intervention for ''Decision Paralysis / Poor Decision Quality.'' Used in the diagnosis to probe whether founders understand which of their decisions are actually high-stakes.', '["RC-517", "RC-518", "RC-519"]', '["INT-016"]', 'Jeff Bezos / Amazon shareholder letters', '2026-07-10 17:57:13.082473+00', '2026-07-10 17:57:13.082473+00') on conflict do nothing;
insert into "frameworks" ("framework_id", "framework_code", "framework_name", "creator", "category", "what_it_is", "problem_it_solves", "stage_relevance", "industry_relevance", "how_alley_uses_it", "linked_root_cause_ids", "linked_intervention_ids", "source_reference", "created_at", "updated_at") values ('65', 'FW-065', 'Burnout Stage Assessment', 'Christina Maslach', 'Founder Psychology', 'A three-stage model for assessing founder burnout: Stage 1 — Emotional Exhaustion (depleted energy), Stage 2 — Cynicism and Detachment (disengagement), Stage 3 — Ineffectiveness (loss of accomplishment). Each stage has distinct symptoms and requires different interventions.', 'Founders who cannot tell whether they are tired, burning out, or already burned out. The model provides a diagnostic framework for the burnout trajectory.', '[1, 2, 3, 4, 5, 6, 7, 8]', '["all"]', 'Referenced in the Founder Behaviour & Decision Patterns document (Doc 5) and the psychological state scoring system (Doc 10). One of the key frameworks for the Distress Protocol in Doc 12.', '["RC-517", "RC-518", "RC-519"]', '["INT-015"]', 'Maslach Burnout Inventory — Christina Maslach (1981)', '2026-07-10 17:57:13.082473+00', '2026-07-10 17:57:13.082473+00') on conflict do nothing;
insert into "frameworks" ("framework_id", "framework_code", "framework_name", "creator", "category", "what_it_is", "problem_it_solves", "stage_relevance", "industry_relevance", "how_alley_uses_it", "linked_root_cause_ids", "linked_intervention_ids", "source_reference", "created_at", "updated_at") values ('66', 'FW-066', 'Immunity to Change', 'Robert Kegan & Lisa Laskow Lahey', 'Founder Psychology', 'A change framework that reveals the hidden psychological commitments that keep founders stuck despite their best intentions. The Immunity Map identifies the gap between what someone wants to change and what they are unconsciously doing to prevent change.', 'Founders who know what they need to do differently but cannot seem to do it — not because of capability gaps but because of hidden competing commitments.', '[1, 2, 3, 4, 5, 6, 7, 8]', '["all"]', 'Referenced in intervention for ''A Real Identity Shift Happens'' (Founder Leadership Evolution section). Used when root causes involve deep behavioural patterns that resist surface-level interventions.', '["RC-517", "RC-518", "RC-519"]', '["INT-092"]', 'Immunity to Change — Kegan & Lahey (2009)', '2026-07-10 17:57:13.082473+00', '2026-07-10 17:57:13.082473+00') on conflict do nothing;
insert into "frameworks" ("framework_id", "framework_code", "framework_name", "creator", "category", "what_it_is", "problem_it_solves", "stage_relevance", "industry_relevance", "how_alley_uses_it", "linked_root_cause_ids", "linked_intervention_ids", "source_reference", "created_at", "updated_at") values ('67', 'FW-067', 'Failure CV Exercise', 'Tina Seelig / Stanford', 'Founder Psychology', 'A reflective exercise where the founder writes a reverse CV documenting their failures, rejections, and setbacks — alongside what each one taught them. Normalises failure as data rather than identity.', 'Founders who are avoiding action because they are catastrophising potential failure. The Failure CV reframes the relationship between founder identity and failure.', '[1, 2, 3, 4, 5]', '["all"]', 'Referenced in intervention for ''Fear of Failure / Imposter Syndrome.'' One of the three immediate next steps for identity-related root causes.', '["RC-517", "RC-518", "RC-519"]', '["INT-014"]', 'Tina Seelig / Stanford d.school (widely attributed)', '2026-07-10 17:57:13.082473+00', '2026-07-10 17:57:13.082473+00') on conflict do nothing;
insert into "frameworks" ("framework_id", "framework_code", "framework_name", "creator", "category", "what_it_is", "problem_it_solves", "stage_relevance", "industry_relevance", "how_alley_uses_it", "linked_root_cause_ids", "linked_intervention_ids", "source_reference", "created_at", "updated_at") values ('68', 'FW-068', 'Three Horizons Framework', 'McKinsey & Company', 'Scaling & Growth', 'A strategic planning framework that allocates attention and resources across three time horizons simultaneously: Horizon 1 (core business — next 1-2 years), Horizon 2 (emerging opportunities — 2-5 years), Horizon 3 (future bets — 5+ years). Prevents short-term thinking from destroying long-term potential.', 'Scaling founders who are so focused on today''s fires that they neglect the investments needed for tomorrow''s growth. The Three Horizons creates structural time for strategic thinking.', '[5, 6, 7, 8]', '["all"]', 'Referenced in interventions for ''Balancing Today and Tomorrow'' and ''Staying Innovative While Organised.'' One of the core strategic frameworks for scaling companies.', '["RC-661", "RC-662", "RC-663"]', '["INT-093"]', 'McKinsey & Company / Baghai, Coley & White (1999)', '2026-07-10 17:57:13.082473+00', '2026-07-10 17:57:13.082473+00') on conflict do nothing;
insert into "frameworks" ("framework_id", "framework_code", "framework_name", "creator", "category", "what_it_is", "problem_it_solves", "stage_relevance", "industry_relevance", "how_alley_uses_it", "linked_root_cause_ids", "linked_intervention_ids", "source_reference", "created_at", "updated_at") values ('69', 'FW-069', 'Blue Ocean Strategy', 'W. Chan Kim & Renée Mauborgne', 'Scaling & Growth', 'A strategy framework for creating uncontested market space by making the competition irrelevant — rather than competing in existing saturated markets. Distinguishes between red oceans (competitive markets) and blue oceans (new value-cost trade-offs).', 'Founders competing on existing dimensions in crowded markets where the only variable is price. Blue Ocean Strategy reveals how to create new value that competitors cannot immediately copy.', '[3, 4, 5, 6, 7]', '["all"]', 'Referenced in interventions for ''Competitors Show Up Fast'' and ''The Market Gets Crowded.'' Used in competitive strategy diagnosis for scaling companies.', '["RC-661", "RC-662", "RC-663"]', '["INT-017", "INT-078", "INT-081"]', 'Blue Ocean Strategy — Kim & Mauborgne (2005)', '2026-07-10 17:57:13.082473+00', '2026-07-10 17:57:13.082473+00') on conflict do nothing;
insert into "frameworks" ("framework_id", "framework_code", "framework_name", "creator", "category", "what_it_is", "problem_it_solves", "stage_relevance", "industry_relevance", "how_alley_uses_it", "linked_root_cause_ids", "linked_intervention_ids", "source_reference", "created_at", "updated_at") values ('70', 'FW-070', E'Porter\\''s Generic Strategies', 'Michael Porter', 'Scaling & Growth', 'Three strategies for achieving sustainable competitive advantage: Cost Leadership (lowest cost producer), Differentiation (unique value that commands premium), and Focus (serving a narrow segment better than anyone). Being stuck in the middle — none of the three — is the most dangerous position.', 'Founders who are trying to be everything to everyone — affordable AND premium AND broad AND niche. The framework forces a strategic choice.', '[4, 5, 6, 7, 8]', '["all"]', 'Referenced in intervention for ''Competitors Show Up Fast.'' Used in the competitive strategy diagnosis for companies facing increasing market pressure.', '["RC-661", "RC-662", "RC-663"]', '["INT-078"]', 'Competitive Strategy — Michael Porter (1980)', '2026-07-10 17:57:13.082473+00', '2026-07-10 17:57:13.082473+00') on conflict do nothing;
insert into "frameworks" ("framework_id", "framework_code", "framework_name", "creator", "category", "what_it_is", "problem_it_solves", "stage_relevance", "industry_relevance", "how_alley_uses_it", "linked_root_cause_ids", "linked_intervention_ids", "source_reference", "created_at", "updated_at") values ('71', 'FW-071', 'CAGE Distance Framework', 'Pankaj Ghemawat', 'Scaling & Growth', 'A framework for evaluating international market entry by assessing four types of distance: Cultural, Administrative, Geographic, and Economic. Helps founders avoid the most common international expansion mistakes.', 'Founders who assume markets that look similar on the surface will behave similarly. The CAGE framework reveals hidden distances that determine whether expansion will succeed.', '[6, 7, 8]', '["all"]', 'Referenced in intervention for ''Going International Brings a Whole New Set of Competitors.'' Used in the international expansion section of the Scaling category.', '["RC-661", "RC-662", "RC-663"]', '["INT-086"]', 'Redefining Global Strategy — Pankaj Ghemawat (2007)', '2026-07-10 17:57:13.082473+00', '2026-07-10 17:57:13.082473+00') on conflict do nothing;
insert into "frameworks" ("framework_id", "framework_code", "framework_name", "creator", "category", "what_it_is", "problem_it_solves", "stage_relevance", "industry_relevance", "how_alley_uses_it", "linked_root_cause_ids", "linked_intervention_ids", "source_reference", "created_at", "updated_at") values ('72', 'FW-072', 'Platform Strategy Framework', 'Geoffrey Parker & Marshall Van Alstyne', 'Scaling & Growth', 'A strategic framework for businesses that create value by facilitating interactions between two or more user groups. Covers network effects, platform design, ecosystem development, and competitive dynamics unique to platform businesses.', 'Platform founders who apply linear business thinking to platform problems — treating the platform like a product company and missing the network effects that determine platform success or failure.', '[4, 5, 6, 7, 8]', '["all"]', 'Referenced in intervention for ''Bigger Platforms Can Box You Out.'' Used in the competitive defensibility diagnosis for marketplace and platform businesses.', '["RC-661", "RC-662", "RC-663"]', '["INT-083"]', 'Platform Revolution — Parker, Van Alstyne & Choudary', '2026-07-10 17:57:13.082473+00', '2026-07-10 17:57:13.082473+00') on conflict do nothing;
insert into "frameworks" ("framework_id", "framework_code", "framework_name", "creator", "category", "what_it_is", "problem_it_solves", "stage_relevance", "industry_relevance", "how_alley_uses_it", "linked_root_cause_ids", "linked_intervention_ids", "source_reference", "created_at", "updated_at") values ('73', 'FW-073', 'Ambidextrous Organisation Framework', 'O''Reilly & Tushman', 'Scaling & Growth', 'A management framework for simultaneously exploiting current business strengths (exploitation) while exploring future opportunities (exploration). Structural and contextual approaches to building ambidexterity.', 'Scaling founders who must optimise the current business while also innovating for the future — two activities that naturally conflict with each other.', '[6, 7, 8]', '["all"]', 'Referenced in intervention for ''Staying Innovative While Also Staying Organised.'' Used in the Founder Leadership Evolution section for Stage 7-9 founders.', '["RC-661", "RC-662", "RC-663"]', '["INT-093"]', 'Lead and Disrupt — O''Reilly & Tushman (2016)', '2026-07-10 17:57:13.082473+00', '2026-07-10 17:57:13.082473+00') on conflict do nothing;
insert into "frameworks" ("framework_id", "framework_code", "framework_name", "creator", "category", "what_it_is", "problem_it_solves", "stage_relevance", "industry_relevance", "how_alley_uses_it", "linked_root_cause_ids", "linked_intervention_ids", "source_reference", "created_at", "updated_at") values ('74', 'FW-074', 'Network Effects Framework', 'Andrew Chen / NFX', 'Scaling & Growth', 'A framework for understanding, designing, and strengthening network effects — where the product becomes more valuable as more people use it. Classifies network effects by type (direct, indirect, data, social, marketplace) and strength.', 'Founders who know they have network effects but do not understand how to strengthen them or defend against competitors who are trying to break them.', '[3, 4, 5, 6, 7]', '["all"]', 'Referenced in intervention for ''Bigger Platforms Can Box You Out.'' Used in the competitive moat diagnosis for network-effect businesses.', '["RC-661", "RC-662", "RC-663"]', '["INT-083"]', 'Andrew Chen / NFX / James Currier', '2026-07-10 17:57:13.082473+00', '2026-07-10 17:57:13.082473+00') on conflict do nothing;
insert into "frameworks" ("framework_id", "framework_code", "framework_name", "creator", "category", "what_it_is", "problem_it_solves", "stage_relevance", "industry_relevance", "how_alley_uses_it", "linked_root_cause_ids", "linked_intervention_ids", "source_reference", "created_at", "updated_at") values ('75', 'FW-075', '7 Powers Framework', 'Hamilton Helmer', 'Scaling & Growth', 'A framework identifying the seven sources of sustainable competitive advantage: Scale Economies, Network Effects, Counter-Positioning, Switching Costs, Branding, Cornered Resource, and Process Power. Each power must be earned and maintained.', 'Founders who cannot articulate what makes their competitive advantage durable. The 7 Powers framework reveals whether the moat is real or imaginary.', '[4, 5, 6, 7, 8]', '["all"]', 'Referenced in intervention for ''The Original Advantage Stops Protecting You.'' Used in the competitive defensibility diagnosis for scaling companies.', '["RC-661", "RC-662", "RC-663"]', '["INT-079"]', '7 Powers: The Foundations of Business Strategy —', '2026-07-10 17:57:13.082473+00', '2026-07-10 17:57:13.082473+00') on conflict do nothing;
insert into "frameworks" ("framework_id", "framework_code", "framework_name", "creator", "category", "what_it_is", "problem_it_solves", "stage_relevance", "industry_relevance", "how_alley_uses_it", "linked_root_cause_ids", "linked_intervention_ids", "source_reference", "created_at", "updated_at") values ('76', 'FW-076', 'Financial Planning & Analysis (FP&A)', 'Corporate finance standard', 'Financial & Revenue', 'A business function and set of practices covering financial forecasting, budgeting, performance analysis, and management reporting. FP&A connects financial data to strategic decision-making.', 'Founders who are reactive about finances — looking at what happened rather than planning for what will happen. FP&A replaces financial surprise with financial foresight.', '[5, 6, 7, 8]', '["all"]', 'Referenced in intervention for ''No Real Financial Planning System.'' Recommended when the root cause is spreadsheet dependence or reactive financial management.', '["RC-694", "RC-695", "RC-696"]', '["INT-067"]', 'Corporate finance standard / widely attributed', '2026-07-10 17:57:13.082473+00', '2026-07-10 17:57:13.082473+00') on conflict do nothing;
insert into "frameworks" ("framework_id", "framework_code", "framework_name", "creator", "category", "what_it_is", "problem_it_solves", "stage_relevance", "industry_relevance", "how_alley_uses_it", "linked_root_cause_ids", "linked_intervention_ids", "source_reference", "created_at", "updated_at") values ('77', 'FW-077', 'Driver-Based Financial Model', 'FP&A best practice', 'Financial & Revenue', 'A financial model built from operational drivers — number of customers, average deal size, churn rate, headcount, pricing — rather than from historical trends. Connects business actions directly to financial outcomes.', 'Founders who build financial models by extrapolating from past numbers without understanding the drivers that create those numbers. Driver-based models reveal which levers actually move the financial needle.', '[4, 5, 6, 7, 8]', '["all"]', 'Referenced in intervention for ''No Real Financial Planning System.'' The recommended approach for replacing static spreadsheets with a living financial model.', '["RC-694", "RC-695", "RC-696"]', '["INT-067"]', 'FP&A best practice / widely attributed', '2026-07-10 17:57:13.082473+00', '2026-07-10 17:57:13.082473+00') on conflict do nothing;
insert into "frameworks" ("framework_id", "framework_code", "framework_name", "creator", "category", "what_it_is", "problem_it_solves", "stage_relevance", "industry_relevance", "how_alley_uses_it", "linked_root_cause_ids", "linked_intervention_ids", "source_reference", "created_at", "updated_at") values ('78', 'FW-078', 'Contribution Margin Analysis', 'Managerial accounting standard', 'Financial & Revenue', 'A profitability analysis that measures revenue minus variable costs for each product, customer segment, or service line. Reveals which parts of the business are actually contributing to covering fixed costs and generating profit.', 'Founders who track total revenue without understanding which customers, products, or services are profitable. Contribution margin reveals where money is being made and where it is being lost.', '[3, 4, 5, 6, 7, 8]', '["all"]', 'Referenced in interventions for ''Profit Margins Quietly Shrink'' and ''Pricing vs Cost Confusion.'' Used in the Manufacturing/D2C and Services industry calibration layers.', '["RC-694", "RC-695", "RC-696"]', '["INT-063", "INT-027"]', 'Managerial accounting standard / widely attributed', '2026-07-10 17:57:13.082473+00', '2026-07-10 17:57:13.082473+00') on conflict do nothing;
insert into "frameworks" ("framework_id", "framework_code", "framework_name", "creator", "category", "what_it_is", "problem_it_solves", "stage_relevance", "industry_relevance", "how_alley_uses_it", "linked_root_cause_ids", "linked_intervention_ids", "source_reference", "created_at", "updated_at") values ('79', 'FW-079', 'Cash Conversion Cycle (CCC)', 'Corporate finance standard', 'Financial & Revenue', 'A metric measuring how long it takes cash to flow from investment in inputs to collection from customers: Days Inventory Outstanding + Days Sales Outstanding - Days Payable Outstanding. Lower CCC means cash flows faster.', 'Manufacturing and services founders who are profitable on paper but cash-poor in reality. The CCC reveals where cash is getting trapped in the business cycle.', '[4, 5, 6, 7, 8]', '["all"]', 'Referenced in intervention for ''Cash Gets Tied Up Unexpectedly.'' Used in the Manufacturing & D2C industry calibration layer as a key operational metric.', '["RC-694", "RC-695", "RC-696"]', '["INT-062"]', 'Corporate finance standard / widely attributed', '2026-07-10 17:57:13.082473+00', '2026-07-10 17:57:13.082473+00') on conflict do nothing;
insert into "frameworks" ("framework_id", "framework_code", "framework_name", "creator", "category", "what_it_is", "problem_it_solves", "stage_relevance", "industry_relevance", "how_alley_uses_it", "linked_root_cause_ids", "linked_intervention_ids", "source_reference", "created_at", "updated_at") values ('80', 'FW-080', 'Net Revenue Retention (NRR)', 'SaaS / subscription standard', 'Financial & Revenue', 'A metric measuring revenue retained from existing customers over a period — including expansion, contraction, and churn. NRR above 100% means the business grows even with zero new customers. NRR below 100% means existing customer revenue is shrinking.', 'SaaS founders who celebrate revenue growth without realising their existing customer base is actually shrinking — masked by new customer acquisition. NRR is the most important health metric for subscription businesses.', '[4, 5, 6, 7, 8]', '["all"]', 'Referenced extensively in the SaaS industry calibration layer (Doc 9). One of the key red flag metrics — SaaS NRR below 100% is a critical signal in the diagnosis.', '["RC-694", "RC-695", "RC-696"]', '["INT-066"]', 'SaaS / subscription industry standard', '2026-07-10 17:57:13.082473+00', '2026-07-10 17:57:13.082473+00') on conflict do nothing;
insert into "frameworks" ("framework_id", "framework_code", "framework_name", "creator", "category", "what_it_is", "problem_it_solves", "stage_relevance", "industry_relevance", "how_alley_uses_it", "linked_root_cause_ids", "linked_intervention_ids", "source_reference", "created_at", "updated_at") values ('81', 'FW-081', 'Scenario Planning Framework', 'Royal Dutch Shell / strategy community', 'Financial & Revenue', 'A strategic planning method that prepares organisations for multiple possible futures rather than betting on a single forecast. Typically models best-case, expected-case, and downside scenarios across key business variables.', 'Founders who plan based on their most optimistic assumptions and have no response prepared when reality diverges. Scenario planning builds strategic resilience.', '[4, 5, 6, 7, 8]', '["all"]', 'Referenced in multiple interventions across Fundraising and Financial categories. Used when the root cause involves revenue forecasting or capital planning assumptions.', '["RC-694", "RC-695", "RC-696"]', '["INT-009", "INT-044"]', 'Royal Dutch Shell (1970s) / widely adopted in strategy', '2026-07-10 17:57:13.082473+00', '2026-07-10 17:57:13.082473+00') on conflict do nothing;
insert into "frameworks" ("framework_id", "framework_code", "framework_name", "creator", "category", "what_it_is", "problem_it_solves", "stage_relevance", "industry_relevance", "how_alley_uses_it", "linked_root_cause_ids", "linked_intervention_ids", "source_reference", "created_at", "updated_at") values ('82', 'FW-082', 'Donor Concentration & 80G Framework', 'NGO / social sector standard', 'Financial & Revenue', 'A financial risk framework specific to NGOs and social enterprises assessing donor concentration risk (% of funding from single donors) and the strategic value of 80G tax exemption status for increasing donation attractiveness in India.', 'Indian NGO founders who are existentially dependent on 1-2 large donors — typically CSR funders — with no diversification strategy. 80G status is a key enabler of domestic fundraising.', '[2, 3, 4, 5, 6]', '["all"]', 'Referenced in the Social Impact & NGO industry calibration layer (Doc 9). The donor concentration threshold (above 50% from single donor) is a critical red flag in the NGO diagnosis.', '["RC-694", "RC-695", "RC-696"]', '[]', 'Indian NGO / FCRA regulatory framework / CAF India', '2026-07-10 17:57:13.082473+00', '2026-07-10 17:57:13.082473+00') on conflict do nothing;
insert into "frameworks" ("framework_id", "framework_code", "framework_name", "creator", "category", "what_it_is", "problem_it_solves", "stage_relevance", "industry_relevance", "how_alley_uses_it", "linked_root_cause_ids", "linked_intervention_ids", "source_reference", "created_at", "updated_at") values ('83', 'FW-083', 'PESTLE Analysis', 'Francis Aguilar', 'Financial & Revenue', 'A strategic environmental scanning framework analysing six external factors: Political, Economic, Social, Technological, Legal, and Environmental. Used for understanding the macro context in which the business operates.', 'Founders who make strategic decisions without understanding the external forces shaping their market. Particularly important for businesses affected by regulation, market cycles, or technology shifts.', '[4, 5, 6, 7, 8]', '["all"]', 'Referenced in interventions for ''Product Mis-Timing'' and ''Going International.'' Used as a market readiness assessment tool in the competitive strategy diagnosis.', '["RC-694", "RC-695", "RC-696"]', '["INT-086", "INT-044"]', 'Environmental Scanning — Francis Aguilar (1967)', '2026-07-10 17:57:13.082473+00', '2026-07-10 17:57:13.082473+00') on conflict do nothing;
